import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def find_good_numbers():
    good_numbers = set()

    # We start with g >= 2. We search for enough values to ensure we find the 20th.
    # Based on initial estimates, setting limits for y0 and g should suffice.
    # Let's iterate g up to 10, and y0 up to 10.

    MAX_G = 10
    MAX_Y0 = 10

    for g in range(2, MAX_G + 1):
        for y0 in range(2, MAX_Y0 + 1):
            for x0 in range(1, y0):
                if gcd(x0, y0) == 1:
                    S = x0**2 + y0**2
                    m = g**2 * S
                    good_numbers.add(m)

    sorted_good_numbers = sorted(list(good_numbers))

    if len(sorted_good_numbers) < 20:
        print(f"Warning: Found only {len(sorted_good_numbers)} numbers with current bounds. Need to increase search limits.")
        return None

    return sorted_good_numbers[19] # 20th smallest

result = find_good_numbers()
